1	import fs from "node:fs/promises";
2	
3	const DEFAULT_AGENT_BUNDLE_FILES = {
4	  default: ["AGENTS.md"],
5	  ceo: ["AGENTS.md", "HEARTBEAT.md", "SOUL.md", "TOOLS.md"],
6	} as const;
7	
8	type DefaultAgentBundleRole = keyof typeof DEFAULT_AGENT_BUNDLE_FILES;
9	
10	function resolveDefaultAgentBundleUrl(role: DefaultAgentBundleRole, fileName: string) {
11	  return new URL(`../onboarding-assets/${role}/${fileName}`, import.meta.url);
12	}
13	
14	export async function loadDefaultAgentInstructionsBundle(role: DefaultAgentBundleRole): Promise<Record<string, string>> {
15	  const fileNames = DEFAULT_AGENT_BUNDLE_FILES[role];
16	  const entries = await Promise.all(
17	    fileNames.map(async (fileName) => {
18	      const content = await fs.readFile(resolveDefaultAgentBundleUrl(role, fileName), "utf8");
19	      return [fileName, content] as const;
20	    }),
21	  );
22	  return Object.fromEntries(entries);
23	}
24	
25	export function resolveDefaultAgentInstructionsBundleRole(role: string): DefaultAgentBundleRole {
26	  return role === "ceo" ? "ceo" : "default";
27	}
